<template><section class="page"><header><h2>维修台账</h2><p>保存维修闭环和物料出入库的不可变业务记录。</p></header><div class="organization-filter"><OrganizationSelect v-model="organizationId" context-key="facility-ledger" /></div><el-table :data="rows" border><el-table-column label="时间" width="170"><template #default="{row}">{{dateTime(row.createTime)}}</template></el-table-column><el-table-column prop="entryType" label="类型" width="140"/><el-table-column prop="repairOrderId" label="报修单ID" min-width="190"/><el-table-column prop="quantity" label="数量" width="100"/><el-table-column prop="amount" label="金额" width="110"/><el-table-column prop="operatorUsername" label="操作人" width="130"/><el-table-column prop="description" label="说明" min-width="260"/></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="search"/></section></template>
<script setup>import{ref,watch}from'vue';import OrganizationSelect from '../../../components/OrganizationSelect.vue';import{maintenanceLedger}from'../api';import{dateTime}from'../labels';const organizationId=ref(''),rows=ref([]),page=ref(1),size=ref(20),total=ref(0);let version=0;const load=async()=>{const current=++version;rows.value=[];total.value=0;if(!organizationId.value)return;const r=await maintenanceLedger({organizationId:organizationId.value,page:page.value-1,size:size.value});if(current!==version)return;rows.value=r.data.content;total.value=r.data.totalElements};const search=()=>{page.value=1;load()};watch(organizationId,load)</script><style scoped>.page{padding:24px}header{margin-bottom:18px}.organization-filter{width:280px;margin-bottom:14px}h2{margin:0 0 6px}p{margin:0;color:#84909a}.el-pagination{margin-top:10px;justify-content:flex-end}</style>
